mapper.select:
/* * SQL-ID : isry.couns.mngr.etxpyreqstdmng.mapper.OvtiWorkEtxpyAplyMngMapper.selectOvtiWorkEtxpyAplyMngList : 시간외수당신청서 LIST * 탈퇴한 종사자의 SAB230 데이터 삭제로 인한 상담원 목록 조회시 이슈 발생으로 상담원 목록 조회 쿼리 변경 * 2023.07.06 수정 - Jeong.Won.Je * SCA100의 DEL_YN = 'N' 조건 삭제 * 2023.07.07 수정 - Jeong.Won.Je */ WITH ZZ AS ( SELECT * FROM ( SELECT T1.USER_ID AS USER_ID , T1.ENFSN_NO AS ENFSN_NO , NVL(T2.RETIRE_YMD, TO_CHAR(SYSDATE, 'YYYYMMDD')) AS RETIRE_YMD FROM SAA200 T1 , SCA100 T2 WHERE 1=1 AND T2.OGDP_INST_NO = '1000000947' AND T1.ENFSN_NO = T2.ENFSN_NO AND NOT EXISTS ( SELECT * FROM SAB230 T3 WHERE T3.USER_ID = T1.USER_ID AND T3.GROUP_AUTHRT_SE_CD != '340' ) )
WHERE RETIRE_YMD > #{YYYYMMDD}
) , PENSN AS ( SELECT NIGHT_WORK_UNTPC_AMT , WIK_OVTIME_UNTPC_AMT , NIGHT_OVTIME_UNTPC_AMT FROM AYC380 /* 근무수당단가관리 */ WHERE 1=1 AND CRTR_YR = SUBSTR(#{YYYYMM}, 0, 4) ) , DAYTIME AS ( SELECT ZZ.USER_ID AS USER_ID , C##RG.DEC_B64(B4.FLNM_ENCPT) AS USER_FLNM , B4.OGDP_DEPT_CD AS DEPT_CD , B2.WORK_YMD AS WORK_YMD , '1' AS OVTIME_WORK_SHAPE_SE_CD , CASE WHEN B3.BGNG_HR = '03:30' THEN FLOOR((B1.CHTT_END_DT - to_date((B2.WORK_YMD || replace(B3.END_HR, ':', '') || '00'), 'YYYY-MM-DD HH24MISS')) * 24 * 60) WHEN B3.BGNG_HR = '07:00' THEN FLOOR((B1.CHTT_END_DT - to_date((B2.WORK_YMD || replace(B3.END_HR, ':', '') || '00'), 'YYYY-MM-DD HH24MISS')) * 24 * 60) WHEN B3.BGNG_HR = '10:30' THEN FLOOR((B1.CHTT_END_DT - to_date((B2.WORK_YMD || replace(B3.END_HR, ':', '') || '00'), 'YYYY-MM-DD HH24MISS')) * 24 * 60) WHEN B3.BGNG_HR = '14:00' THEN FLOOR((B1.CHTT_END_DT - to_date((B2.WORK_YMD || replace(B3.END_HR, ':', '') || '00'), 'YYYY-MM-DD HH24MISS')) * 24 * 60) WHEN B3.BGNG_HR = '17:30' THEN CASE WHEN FLOOR((B1.CHTT_END_DT - to_date((B2.WORK_YMD || replace(B3.END_HR, ':', '') || '00'), 'YYYY-MM-DD HH24MISS')) * 24 * 60) > 31 THEN 30 ELSE FLOOR((B1.CHTT_END_DT - to_date((B2.WORK_YMD || replace(B3.END_HR, ':', '') || '00'), 'YYYY-MM-DD HH24MISS')) * 24 * 60) END ELSE 0 END AS WTIME FROM ZZ , AYB200 B1 /* 채팅이력 */ , AYC100 B2 /* 근무배정표_일별 */ , AYC110 B3 /* 근무배정표_월별 */ , SCA100 B4 /* 종사자 */ WHERE 1=1 AND B1.OVTIME_WORK_YMD IS NOT NULL AND SUBSTR(B1.OVTIME_WORK_YMD, 0, 6) = #{YYYYMM} AND B1.CNSLTNT_ID = ZZ.USER_ID AND B1.DEL_YN = 'N' AND B4.ENFSN_NO = ZZ.ENFSN_NO AND B2.USER_ID = B1.CNSLTNT_ID AND B2.WORK_YMD = B1.OVTIME_WORK_YMD AND B2.DEL_YN = 'N' AND B3.BIZ_PLAN_MNG_NO = B2.BIZ_PLAN_MNG_NO AND B3.DEL_YN = 'N' ) , NIGHT AS ( SELECT ZZ.USER_ID AS USER_ID , C##RG.DEC_B64(B4.FLNM_ENCPT) AS USER_FLNM , B4.OGDP_DEPT_CD AS DEPT_CD , B2.WORK_YMD AS WORK_YMD , '2' AS OVTIME_WORK_SHAPE_SE_CD , CASE WHEN B3.BGNG_HR = '20:30' THEN FLOOR((B1.CHTT_END_DT - (to_date((B2.WORK_YMD || replace(B3.END_HR, ':', '') || '00'), 'YYYY-MM-DD HH24MISS')+1)) * 24 * 60) WHEN B3.BGNG_HR = '00:00' THEN FLOOR((B1.CHTT_END_DT - to_date((B2.WORK_YMD || replace(B3.END_HR, ':', '') || '00'), 'YYYY-MM-DD HH24MISS')) * 24 * 60) WHEN B3.BGNG_HR = '20:00' THEN FLOOR((B1.CHTT_END_DT - (to_date((B2.WORK_YMD || replace(B3.END_HR, ':', '') || '00'), 'YYYY-MM-DD HH24MISS')+1)) * 24 * 60) WHEN B3.BGNG_HR = '17:30' THEN CASE WHEN FLOOR((B1.CHTT_END_DT - to_date((B2.WORK_YMD || replace(B3.END_HR, ':', '') || '00'), 'YYYY-MM-DD HH24MISS')) * 24 * 60) > 31 THEN FLOOR((B1.CHTT_END_DT - to_date((B2.WORK_YMD || replace(B3.END_HR, ':', '') || '00'), 'YYYY-MM-DD HH24MISS')) * 24 * 60) - 30 ELSE 0 END ELSE 0 END AS WTIME FROM ZZ , AYB200 B1 /* 채팅이력 */ , AYC100 B2 /* 근무배정표_일별 */ , AYC110 B3 /* 근무배정표_월별 */ , SCA100 B4 /* 종사자 */ WHERE 1=1 AND B1.OVTIME_WORK_YMD IS NOT NULL AND SUBSTR(B1.OVTIME_WORK_YMD, 0, 6) = #{YYYYMM} AND B1.CNSLTNT_ID = ZZ.USER_ID AND B1.DEL_YN = 'N' AND B4.ENFSN_NO = ZZ.ENFSN_NO AND B2.USER_ID = B1.CNSLTNT_ID AND B2.WORK_YMD = B1.OVTIME_WORK_YMD AND B2.DEL_YN = 'N' AND B3.BIZ_PLAN_MNG_NO = B2.BIZ_PLAN_MNG_NO AND B3.DEL_YN = 'N' ) SELECT NVL(APRV_TB.CONSTT_ID, INQ_TB.USER_ID) AS CONSTT_ID , INQ_TB.USER_FLNM AS CONSTT_NM , INQ_TB.DEPT_CD AS DEPT_CD , NVL(APRV_TB.OVTIME_WORK_SHAPE_SE_CD, INQ_TB.OVTIME_WORK_SHAPE_SE_CD) AS OVTIME_WORK_SHAPE_SE_CD , NVL(APRV_TB.EXCESS_WORK_HR, INQ_TB.TOTAL_WORK_HR) AS EXCESS_WORK_HR , NVL(APRV_TB.PENSN_RCGNTN_HR, INQ_TB.RCGNTN_WORK_HR) AS PENSN_RCGNTN_HR , NVL(APRV_TB.PENSN_SUM_AMT, INQ_TB.TOTAL_AMT) AS PENSN_SUM_AMT , NVL(APRV_TB.APRV_YN, 'N') AS APRV_YN FROM ( SELECT TT1.USER_ID , TT1.USER_FLNM , TT1.DEPT_CD , TT1.OVTIME_WORK_SHAPE_SE_CD , TT1.TOTAL_WORK_HR , TT1.RCGNTN_WORK_HR , TRUNC((TT1.RCGNTN_WORK_HR / 10) * (CASE WHEN TT1.OVTIME_WORK_SHAPE_SE_CD = '1' THEN TT2.WIK_OVTIME_UNTPC_AMT WHEN TT1.OVTIME_WORK_SHAPE_SE_CD = '2' THEN TT2.NIGHT_OVTIME_UNTPC_AMT ELSE 0 END ) , -1) AS TOTAL_AMT FROM ( SELECT USER_ID , USER_FLNM , DEPT_CD , OVTIME_WORK_SHAPE_SE_CD , SUM(WTIME) AS TOTAL_WORK_HR , TRUNC(SUM(WTIME), -1) AS RCGNTN_WORK_HR FROM DAYTIME GROUP BY USER_ID, USER_FLNM, DEPT_CD, OVTIME_WORK_SHAPE_SE_CD UNION ALL SELECT USER_ID , USER_FLNM , DEPT_CD , OVTIME_WORK_SHAPE_SE_CD , SUM(WTIME) AS TOTAL_WORK_HR , TRUNC(SUM(WTIME), -1) AS RCGNTN_WORK_HR FROM NIGHT GROUP BY USER_ID, USER_FLNM, DEPT_CD, OVTIME_WORK_SHAPE_SE_CD ) TT1 , PENSN TT2 WHERE TT1.TOTAL_WORK_HR != 0 ) INQ_TB LEFT OUTER JOIN ( SELECT * FROM AYC370 /* 시간외근무수당 */ WHERE RLVT_YM = #{YYYYMM} ) APRV_TB ON INQ_TB.USER_ID = APRV_TB.CONSTT_ID AND INQ_TB.OVTIME_WORK_SHAPE_SE_CD = APRV_TB.OVTIME_WORK_SHAPE_SE_CD ORDER BY INQ_TB.USER_FLNM ASC

/* * SQL-ID : isry.couns.mngr.etxpyreqstdmng.mapper.OvtiWorkEtxpyAplyMngMapper.selectOvtiWorkEtxpyAplyMngDetail1 : 주간시간외수당 list * 작성자 : Jeong.Won.Je */ WITH ZZ AS ( SELECT #{YYYYMM} AS YYYYMM , #{USER_ID} AS USER_ID FROM DUAL ) , Z1 AS (
SELECT T1.CNSLTNT_ID AS USER_ID /* 상담사 아이디 */ , T3.FLNM_ENCPT AS FLNM /* 상담사 이름 */ , T1.CRT_YMD AS WORK_YMD /* 연월일 */ , to_char(T1.WORK_BGNG_DT, 'YYYY-MM-DD AM HH24:MI:SS') AS WORK_BGNG_DT /* 시작시간 */ , to_char(T1.HR_ELSE_WORK_DT, 'YYYY-MM-DD AM HH24:MI:SS') AS CHTT_END_DT /* 퇴근시간 */ , CASE WHEN TO_CHAR(T1.WORK_END_DT, 'HH:MI') = '07:30' OR TO_CHAR(T1.WORK_END_DT, 'HH:MI') = '11:00' OR TO_CHAR(T1.WORK_END_DT, 'HH:MI') = '14:30' OR TO_CHAR(T1.WORK_END_DT, 'HH:MI') = '18:00' THEN T1.HR_ELSE_WORK_APLY_HR WHEN TO_CHAR(T1.WORK_END_DT, 'HH:MI') = '21:30' AND T1.HR_ELSE_WORK_APLY_HR > 31 THEN 30 WHEN TO_CHAR(T1.WORK_END_DT, 'HH:MI') = '21:30' THEN T1.HR_ELSE_WORK_APLY_HR ELSE 0 END AS WTIME /* 시간외시간 */ , 0 AS VCATN_YN /* 휴가 여부 */ FROM AYC300 T1 /* 업무보고서 */ , SAA200 T2 /* 사용자 */ , SCA100 T3 /* 종사자 */ WHERE 1=1 AND T1.CNSLTNT_ID = T2.USER_ID AND T2.ENFSN_NO = T3.ENFSN_NO AND T3.OGDP_DEPT_CD = '326' AND TO_CHAR(T1.HR_ELSE_WORK_DT, 'YYYYMM') = #{YYYYMM} AND T1.CNSLTNT_ID = #{USER_ID}
SELECT T5.USER_ID , T4.FLNM_ENCPT AS FLNM , T2.WORK_YMD , CASE WHEN T3.BGNG_HR = '03:30' THEN FLOOR((T1.CHTT_END_DT - to_date((T2.WORK_YMD || replace(T3.END_HR,':','') || '00'), 'YYYY-MM-DD HH24MISS')) * 24 * 60) WHEN T3.BGNG_HR = '07:00' THEN FLOOR((T1.CHTT_END_DT - to_date((T2.WORK_YMD || replace(T3.END_HR,':','') || '00'), 'YYYY-MM-DD HH24MISS')) * 24 * 60) WHEN T3.BGNG_HR = '10:30' THEN FLOOR((T1.CHTT_END_DT - to_date((T2.WORK_YMD || replace(T3.END_HR,':','') || '00'), 'YYYY-MM-DD HH24MISS')) * 24 * 60) WHEN T3.BGNG_HR = '14:00' THEN FLOOR((T1.CHTT_END_DT - to_date((T2.WORK_YMD || replace(T3.END_HR,':','') || '00'), 'YYYY-MM-DD HH24MISS')) * 24 * 60) WHEN T3.BGNG_HR = '17:30' THEN CASE WHEN FLOOR((T1.CHTT_END_DT - to_date((T2.WORK_YMD || replace(T3.END_HR,':','') || '00'), 'YYYY-MM-DD HH24MISS')) * 24 * 60) > 31 THEN 30 ELSE FLOOR((T1.CHTT_END_DT - to_date((T2.WORK_YMD || replace(T3.END_HR,':','') || '00'), 'YYYY-MM-DD HH24MISS')) * 24 * 60) END ELSE 0 END AS WTIME , to_char(to_date((T2.WORK_YMD || replace(T3.BGNG_HR,':','') || '00'), 'YYYY-MM-DD HH24MISS'), 'YYYY-MM-DD AM HH24:MI:SS') AS WORK_BGNG_DT , to_char(T1.CHTT_END_DT, 'YYYY-MM-DD AM HH24:MI:SS') AS CHTT_END_DT , ( SELECT COUNT(*) FROM ( SELECT T6.USER_ID , T6.VCATN_SE_CD , T6.VCATN_BGNG_YMD , T6.VCATN_END_YMD FROM AYC130 T6 /* 사이버1388휴가 */ WHERE 1=1 AND T6.USER_ID = T2.USER_ID AND T2.WORK_YMD BETWEEN T6.VCATN_BGNG_YMD AND T6.VCATN_END_YMD AND T6.APRV_STTS_SE_CD = '2' AND T6.DEL_YN = 'N' GROUP BY T6.USER_ID, T6.VCATN_SE_CD, T6.VCATN_BGNG_YMD, T6.VCATN_END_YMD ) ) AS VCATN_YN FROM ZZ , AYB200 T1 /* 채팅이력 */ , AYC100 T2 /* 근무배정표_일별 */ , AYC110 T3 /* 근무배정표_월별 */ , SCA100 T4 /* 종사자 테이블 */ , SAA200 T5 /* 사용자 테이블 */ WHERE 1=1 AND T3.BIZ_PLAN_MNG_NO = T2.BIZ_PLAN_MNG_NO AND T2.WORK_YMD = T1.OVTIME_WORK_YMD AND T2.USER_ID = T1.CNSLTNT_ID AND T5.ENFSN_NO = T4.ENFSN_NO AND T5.USER_ID = T2.USER_ID AND T2.USER_ID = ZZ.USER_ID AND substr(T1.OVTIME_WORK_YMD, 0, 6) = ZZ.YYYYMM AND T1.OVTIME_WORK_YMD IS NOT NULL
)
SELECT Z1.USER_ID , Z1.FLNM , Z1.WORK_YMD , Z1.WTIME AS EXCESS_WORK_HR , Z1.WORK_BGNG_DT , Z1.CHTT_END_DT , SUM(Z1.WTIME) OVER() AS SSUM , TRUNC(SUM(Z1.WTIME) OVER(), -1) AS RCGNTN_HR , SUM(Z1.WTIME /10 * FF.WIK_OVTIME_UNTPC_AMT) OVER() AS AAMT , TRUNC(TRUNC(SUM(Z1.WTIME) OVER(), -1) / 10 * FF.NIGHT_OVTIME_UNTPC_AMT, -1) AS RCGNTN_AMT , Z1.VCATN_YN AS VCATN_YN FROM Z1 INNER JOIN AYC380 FF /* 근무수당단가관리 */ ON 1=1 AND FF.CRTR_YR = SUBSTR(Z1.WORK_YMD, 1, 4) WHERE 1=1 AND Z1.VCATN_YN != 1 AND Z1.WTIME != 0

/* * SQL-ID : isry.couns.mngr.etxpyreqstdmng.mapper.OvtiWorkEtxpyAplyMngMapper.selectOvtiWorkEtxpyAplyMngDetail2 : 야간시간외수당 list * 작성자 : Jeong.Won.Je */ WITH ZZ AS ( SELECT #{YYYYMM} AS YYYYMM , #{USER_ID} AS USER_ID FROM DUAL ) , Z1 AS (
SELECT T1.CNSLTNT_ID AS USER_ID /* 상담사 아이디 */ , T3.FLNM_ENCPT AS FLNM /* 상담사 이름 */ , T1.CRT_YMD AS WORK_YMD /* 연월일 */ , to_char(T1.WORK_BGNG_DT, 'YYYY-MM-DD AM HH24:MI:SS') AS WORK_BGNG_DT /* 시작시간 */ , to_char(T1.HR_ELSE_WORK_DT, 'YYYY-MM-DD AM HH24:MI:SS') AS CHTT_END_DT /* 퇴근시간 */ , CASE WHEN TO_CHAR(T1.WORK_END_DT, 'HH:MI') = '00:00' OR TO_CHAR(T1.WORK_END_DT, 'HH:MI') = '00:30' OR TO_CHAR(T1.WORK_END_DT, 'HH:MI') = '04:00' THEN T1.HR_ELSE_WORK_APLY_HR WHEN TO_CHAR(T1.WORK_END_DT, 'HH:MI') = '21:30' AND T1.HR_ELSE_WORK_APLY_HR > 31 THEN T1.HR_ELSE_WORK_APLY_HR - 30 ELSE 0 END AS WTIME /* 시간외시간 */ , 0 AS VCATN_YN /* 휴가여부 */ FROM ZZ , AYC300 T1 /* 업무보고서 */ , SAA200 T2 /* 사용자 */ , SCA100 T3 /* 종사자 */ WHERE 1=1 AND T1.CNSLTNT_ID = T2.USER_ID AND T2.ENFSN_NO = T3.ENFSN_NO AND T3.OGDP_DEPT_CD = '326' AND TO_CHAR(T1.HR_ELSE_WORK_DT, 'YYYYMM') = ZZ.YYYYMM AND T1.CNSLTNT_ID = ZZ.USER_ID
SELECT T5.USER_ID , T4.FLNM_ENCPT AS FLNM , T2.WORK_YMD , CASE WHEN T3.BGNG_HR = '20:30' THEN FLOOR((T1.CHTT_END_DT - (to_date((T2.WORK_YMD || replace(T3.END_HR,':','') || '00'), 'YYYY-MM-DD HH24MISS')+1)) * 24 * 60) WHEN T3.BGNG_HR = '00:00' THEN FLOOR((T1.CHTT_END_DT - to_date((T2.WORK_YMD || replace(T3.END_HR,':','') || '00'), 'YYYY-MM-DD HH24MISS')) * 24 * 60) WHEN T3.BGNG_HR = '20:00' THEN FLOOR((T1.CHTT_END_DT - (to_date((T2.WORK_YMD || replace(T3.END_HR,':','') || '00'), 'YYYY-MM-DD HH24MISS')+1)) * 24 * 60) WHEN T3.BGNG_HR = '17:30' THEN CASE WHEN FLOOR((T1.CHTT_END_DT - to_date((T2.WORK_YMD || replace(T3.END_HR,':','') || '00'), 'YYYY-MM-DD HH24MISS')) * 24 * 60) > 31 THEN FLOOR((T1.CHTT_END_DT - to_date((T2.WORK_YMD || replace(T3.END_HR,':','') || '00'), 'YYYY-MM-DD HH24MISS')) * 24 * 60) -30 ELSE 0 END ELSE 0 END AS WTIME , to_char(to_date((T2.WORK_YMD || replace(T3.BGNG_HR,':','') || '00'), 'YYYY-MM-DD HH24MISS'), 'YYYY-MM-DD AM HH24:MI:SS') AS WORK_BGNG_DT , to_char(T1.CHTT_END_DT, 'YYYY-MM-DD AM HH24:MI:SS') AS CHTT_END_DT , ( SELECT COUNT(*) FROM ( SELECT T6.USER_ID , T6.VCATN_SE_CD , T6.VCATN_BGNG_YMD , T6.VCATN_END_YMD FROM AYC130 T6 /* 사이버1388휴가 */ WHERE 1=1 AND T6.USER_ID = T2.USER_ID AND T2.WORK_YMD BETWEEN T6.VCATN_BGNG_YMD AND T6.VCATN_END_YMD AND T6.APRV_STTS_SE_CD = '2' AND T6.DEL_YN = 'N' GROUP BY T6.USER_ID, T6.VCATN_SE_CD, T6.VCATN_BGNG_YMD, T6.VCATN_END_YMD ) ) AS VCATN_YN FROM ZZ , AYB200 T1 /* 채팅이력 */ , AYC100 T2 /* 근무배정표_일별 */ , AYC110 T3 /* 근무배정표_월별 */ , SCA100 T4 /* 종사자 테이블 */ , SAA200 T5 /* 사용자 테이블 */ WHERE 1=1 AND T3.BIZ_PLAN_MNG_NO = T2.BIZ_PLAN_MNG_NO AND T2.WORK_YMD = T1.OVTIME_WORK_YMD AND T2.USER_ID = T1.CNSLTNT_ID AND T5.ENFSN_NO = T4.ENFSN_NO AND T5.USER_ID = T2.USER_ID AND T2.USER_ID = ZZ.USER_ID AND substr(T1.OVTIME_WORK_YMD, 0, 6) = ZZ.YYYYMM AND T1.OVTIME_WORK_YMD IS NOT NULL
)
SELECT Z1.USER_ID , Z1.FLNM , Z1.WORK_YMD , Z1.WTIME AS EXCESS_WORK_HR , Z1.WORK_BGNG_DT , Z1.CHTT_END_DT , SUM(Z1.WTIME) OVER() AS SSUM , TRUNC(SUM(Z1.WTIME) OVER(), -1) AS RCGNTN_HR , TRUNC(SUM(Z1.WTIME) OVER(), -1) / 10 * FF.NIGHT_OVTIME_UNTPC_AMT AS AAMT , TRUNC(TRUNC(SUM(Z1.WTIME) OVER(), -1) / 10 * FF.NIGHT_OVTIME_UNTPC_AMT, -1) AS RCGNTN_AMT , Z1.VCATN_YN AS VCATN_YN FROM Z1 INNER JOIN AYC380 FF /* 근무수당단가관리 */ ON 1=1 AND FF.CRTR_YR = SUBSTR(Z1.WORK_YMD, 1, 4) WHERE 1=1 AND Z1.VCATN_YN != 1 AND Z1.WTIME != 0
